offsets=np.cumsum([0]+[len(o['triangles']) for o in geometry['objects']])
lookup=np.full(int(offsets[-1]),-1,dtype=int)
for index,reg in enumerate(regions):
 for low,high in reg['source_triangle_index_ranges']: lookup[offsets[reg['object_index']]+low:offsets[reg['object_index']]+high+1]=index
for view in ['SCENE','LEFT','BACK','TOP']:
 frame=buffers[view]; tids=frame['triangle_ids']; labels=np.full(tids.shape,-1,dtype=int); valid=tids>=0; labels[valid]=lookup[tids[valid]]
 # Unsupported source triangles retain distinct labels, different from background and supported patches.
 unsupported=valid & (labels<0); labels[unsupported]=1000+tids[unsupported]
 color=frame['color'].astype(float); boundary=np.zeros(labels.shape,dtype=bool)
 for dy,dx in [(0,1),(1,0)]:
  a=(slice(0,512-dy),slice(0,512-dx)); b=(slice(dy,512),slice(dx,512))
  contrasting=(labels[a]!=labels[b]) & (np.linalg.norm(color[a]-color[b],axis=2)>=24)
  boundary[a]|=contrasting; boundary[b]|=contrasting
 if view=='TOP': print('TOP roof',np.sum(labels==25),np.sum((labels==25)&boundary))
 for index,reg in enumerate(regions):
  wp=reg['complete_witness_pixel_index']
  if wp is not None:
   p=pixels[wp]
   if imgs[p['image_index']]['view_name']==view:
    count=int(np.sum(labels==index)); bc=int(np.sum((labels==index)&boundary)); print('WITNESS',index,objects[reg['object_index']]['object_name'],reg['source_triangle_index_ranges'],view,count,bc,'matches',count==p['visible_surface_pixels'] and bc==p['contrasting_boundary_pixels'])
print('COMPLETE SET BY OBJECT')
for obj in objects:
 entries=[]
 for index,reg in enumerate(regions):
  if reg['object_index']==obj['object_index']:
   groups_for=[groups[g] for g in reg['unobserved_view_group_indices']]
   entries.append({'triangles':reg['source_triangle_index_ranges'],'region_index':index,'state':reg['status'],'reason':reg['unobserved_reason'],'view_groups':groups_for})
 print(obj['object_index'],obj['object_name'],json.dumps(sorted(entries,key=lambda r:r['triangles'])))
